#include "../sortedcontainers.h"
#include <iostream>

int main(int argc, char* argv[]) {
    int n = 6;
    if (argc > 1) {
        n = std::atoi(argv[1]);
    }

    SortedSet<int> s1, s2;
    for (int i = 0; i < n; i++) {
        s1.insert(i);
        s2.insert(i*2);
    }

    auto s3 = s1.union_with(s2);

    std::cout << s1.size() << std::endl;
    std::cout << s2.size() << std::endl;
    std::cout << s3.size() << std::endl;

    for (int i = 0; i < n; i++) {
        std::cout << s3.contains(i) << " ";
    }
    std::cout << std::endl;
    return 0;
}
